#!/bin/sh
set -eu
# Passwords generated by init-env are hex, so substitution cannot introduce YAML syntax.
case "$SQL_PASSWORD" in *[!a-f0-9]*|'') echo 'Generated hex Temporal password required' >&2; exit 1;; esac
sed "s/__SQL_PASSWORD__/$SQL_PASSWORD/g" /stand/config.template.yaml > /tmp/temporal.yaml
exec temporal-server --config-file /tmp/temporal.yaml start
